 82	  }
 83	  if (storeName === STORE_NAMES.resumes && !RESUME_STATUSES.includes(value.status as never)) {
 84	    throw new Error("Invalid Resume.status");
 85	  }
 86	  if (storeName === STORE_NAMES.interviews) {
 87	    if (!INTERVIEW_STATUSES.includes(value.status as never)) throw new Error("Invalid Interview.status");
