100	function payloadRecords(payload: BackupPayload): Map<ImportableStoreName, unknown[]> {
101	  const records = new Map<ImportableStoreName, unknown[]>();
102	  for (const storeName of allowedBackupStores()) records.set(storeName, payload.stores[storeName] ?? []);
