107	async function decodeOriginalFile(file: EncodedOriginalFile): Promise<StoredFile> {
108	  const binary = atob(file.bytes);
109	  const bytes = new Uint8Array(binary.length);
110	  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
111	  const blob = await new Response(bytes, { headers: { "content-type": file.mimeType } }).blob();
112	  return { id: file.id, createdAt: file.createdAt, updatedAt: file.updatedAt, ownerType: file.ownerType, ownerId: file.ownerId, fileName: file.fileName, fileType: file.fileType, blob };
113	}
