115	async function readLocalIds(database: IDBDatabase): Promise<Map<ImportableStoreName, Set<string>>> {
116	  return runTransaction(database, IMPORTABLE_STORES, "readonly", async (transaction) => {
117	    const result = new Map<ImportableStoreName, Set<string>>();
118	    for (const storeName of IMPORTABLE_STORES) {
119	      const rows = await requestToPromise<Array<{ id?: unknown }>>(transaction.objectStore(storeName).getAll());
120	      result.set(storeName, new Set(rows.flatMap((row) => typeof row.id === "string" ? [row.id] : [])));
121	    }
122	    return result;
123	  });
124	}
