126	export async function prepareBackupImport(
127	  database: IDBDatabase,
128	  encryptedInput: unknown,
129	  password: string,
130	): Promise<BackupImportSession> {
131	  const payload = await decryptBackup(encryptedInput, password);
132	  const records = payloadRecords(payload);
133	  for (const [storeName, rows] of records) {
134	    if (!Array.isArray(rows)) throw new Error(`Invalid backup store: ${storeName}`);
135	    for (const row of rows) assertValidRecord(storeName, row);
136	  }
137	  const localIds = await readLocalIds(database);
138	  const decodedOriginalFiles = await Promise.all((payload.originalFiles ?? []).map(decodeOriginalFile));
139	  const conflicts: BackupConflict[] = [];
140	  for (const [storeName, rows] of records) {
141	    const ids = localIds.get(storeName) ?? new Set<string>();
142	    for (const row of rows as Array<{ id: string }>) {
143	      if (ids.has(row.id)) conflicts.push({ storeName, id: row.id, defaultResolution: "keep-local" });
144	    }
145	  }
146	  const storeCounts = Object.fromEntries(IMPORTABLE_STORES.map((storeName) => [storeName, records.get(storeName)?.length ?? 0])) as Record<ImportableStoreName, number>;
147	  const blobCount = payload.originalFiles?.length ?? 0;
148	  return { version: 1, kind: payload.kind, backupVersion: 1, backupKind: payload.kind, payload, storeCounts, counts: storeCounts, blobCount, originalFileCount: blobCount, conflicts, decodedOriginalFiles };
149	}
