151	function resolutionMap(session: BackupImportSession, resolutions?: BackupResolutions | null): Map<string, ImportResolution> {
152	  if (resolutions === null) throw new Error("Import conflict resolution cancelled");
153	  const result = new Map<string, ImportResolution>();
154	  for (const conflict of session.conflicts) result.set(`${conflict.storeName}:${conflict.id}`, "keep-local");
155	  const entries: BackupConflictResolution[] = Array.isArray(resolutions)
156	    ? [...resolutions]
157	    : resolutions instanceof Map
158	      ? [...resolutions.entries()].map(([key, resolution]) => {
159	        const separator = key.indexOf(":");
160	        return { storeName: key.slice(0, separator) as ImportableStoreName, id: key.slice(separator + 1), resolution };
161	      })
162	      : Object.entries(resolutions ?? {}).map(([key, resolution]) => {
163	        const separator = key.indexOf(":");
164	        return { storeName: key.slice(0, separator) as ImportableStoreName, id: key.slice(separator + 1), resolution };
165	      });
166	  for (const resolution of entries) {
167	    if (!IMPORTABLE_STORES.includes(resolution.storeName) || !["keep-local", "use-backup", "import-copy"].includes(resolution.resolution)) {
168	      throw new Error("Invalid import conflict resolution");
169	    }
170	    if (!session.conflicts.some((item) => item.storeName === resolution.storeName && item.id === resolution.id)) {
171	      throw new Error("Resolution does not match a conflict");
172	    }
173	    result.set(`${resolution.storeName}:${resolution.id}`, resolution.resolution);
174	  }
175	  return result;
176	}
