184	function remapRecord(storeName: ImportableStoreName, source: Record<string, unknown>, ids: Map<string, string>): Record<string, unknown> {
185	  const record: Record<string, unknown> = { ...source, id: ids.get(`${storeName}:${String(source.id)}`) ?? source.id };
186	  const fieldMap: Partial<Record<string, ImportableStoreName>> = {
187	    resumeId: STORE_NAMES.resumes,
188	    currentResumeId: STORE_NAMES.resumes,
189	    originalFileId: STORE_NAMES.originalFiles,
190	    jdFileId: STORE_NAMES.originalFiles,
191	    jobDescriptionId: STORE_NAMES.jobDescriptions,
192	    applicationId: STORE_NAMES.applications,
193	    stageId: STORE_NAMES.stages,
194	    interviewId: STORE_NAMES.interviews,
195	  };
196	  for (const [field, targetStore] of Object.entries(fieldMap)) {
197	    if (field in record) record[field] = remapValue(record[field], ids, targetStore);
198	  }
199	  if (storeName === STORE_NAMES.applicationTimelineEvents) {
200	    const type = record.type;
201	    const targetStore = type === "resume-changed" ? STORE_NAMES.resumes : type === "stage-changed" ? STORE_NAMES.stages : undefined;
202	    if (targetStore) {
203	      record.fromValue = remapValue(record.fromValue, ids, targetStore);
204	      record.toValue = remapValue(record.toValue, ids, targetStore);
205	    }
206	  }
207	  if (storeName === STORE_NAMES.originalFiles) record.ownerId = remapValue(record.ownerId, ids, record.ownerType === "resume" ? STORE_NAMES.resumes : STORE_NAMES.jobDescriptions);
208	  return record;
209	}
