211	export function buildImportPlan(
212	  session: BackupImportSession,
213	  resolutions?: BackupResolutions | null,
214	  options: BuildImportPlanOptions = {},
215	): ImportPlan {
216	  const resolutionsByKey = resolutionMap(session, resolutions);
217	  const records = payloadRecords(session.payload);
218	  const ids = new Map<string, string>();
219	  for (const conflict of session.conflicts) {
220	    if (resolutionsByKey.get(`${conflict.storeName}:${conflict.id}`) === "import-copy") {
221	      const nextId = options.createId?.(conflict.storeName, conflict.id) ?? DEFAULT_ID(conflict.storeName, conflict.id);
222	      if (!nextId) throw new Error("Import copy ID is required");
223	      ids.set(`${conflict.storeName}:${conflict.id}`, nextId);
224	    }
225	  }
226	  const output: Partial<Record<ImportableStoreName, unknown[]>> = {};
227	  const operations: ImportOperation[] = [];
228	  for (const storeName of IMPORTABLE_STORES) {
229	    const rows = records.get(storeName) ?? [];
230	    const selected: unknown[] = [];
231	    for (const source of rows as Array<Record<string, unknown>>) {
232	      assertValidRecord(storeName, source);
233	      const key = `${storeName}:${String(source.id)}`;
234	      const resolution = resolutionsByKey.get(key);
235	      if (resolution === "keep-local") continue;
236	      const remapped = remapRecord(storeName, source, ids);
237	      if (storeName === STORE_NAMES.originalFiles) {
238	        const decoded = session.decodedOriginalFiles.find((file) => file.id === source.id);
239	        if (!decoded) throw new Error(`Missing decoded original file: ${String(source.id)}`);
240	        const file = { ...decoded, id: String(remapped.id), ownerId: String(remapped.ownerId) };
241	        selected.push(file);
242	        operations.push({ storeName, record: file, overwrite: resolution === "use-backup" });
243	      } else {
244	        selected.push(remapped);
245	        operations.push({ storeName, record: remapped, overwrite: resolution === "use-backup" });
246	      }
247	    }
248	    output[storeName] = selected;
249	  }
250	  return { kind: session.kind, records: output, operations };
251	}
