253	export async function commitBackupImport(database: IDBDatabase, plan: ImportPlan): Promise<void> {
254	  for (const operation of plan.operations) assertValidRecord(operation.storeName, operation.record);
255	  const stores = IMPORTABLE_STORES;
256	  await runTransaction(database, stores, "readwrite", async (transaction) => {
257	    for (const operation of plan.operations) {
258	      const store = transaction.objectStore(operation.storeName);
259	      await requestToPromise(operation.overwrite ? store.put(operation.record) : store.add(operation.record));
260	    }
261	  });
262	}
