186	export async function prepareBackupImport(
187	  database: IDBDatabase,
188	  encryptedInput: unknown,
189	  password: string,
190	): Promise<BackupImportSession> {
191	  const payload = await decryptBackup(encryptedInput, password);
192	  const records = payloadRecords(payload);
193	  for (const [storeName, rows] of records) {
194	    if (!Array.isArray(rows)) throw new Error(`Invalid backup store: ${storeName}`);
195	    const seenIds = new Set<string>();
196	    if (storeName !== STORE_NAMES.originalFiles) {
197	      for (const row of rows) {
198	        assertValidRecord(storeName, row);
199	        if (seenIds.has(row.id)) throw new Error(`Duplicate record id in store: ${storeName}`);
200	        seenIds.add(row.id);
201	      }
202	    } else {
203	      for (const row of rows) {
204	        if (!isObject(row) || typeof row.id !== "string" || !row.id) throw new Error("Invalid original file record");
205	        if (seenIds.has(row.id)) throw new Error(`Duplicate record id in store: ${storeName}`);
206	        seenIds.add(row.id);
207	      }
208	    }
209	  }
210	  const localIds = await readLocalIds(database);
